import type { Metadata } from "next";
import { SITE } from "@/lib/catalog";
import { privateRobots, publicRobots } from "@/lib/seo";

export const OG_LOCALE = "en_US";
/** Generated by app/opengraph-image.tsx. */
export const DEFAULT_OG_IMAGE = { url: `${SITE.url}/opengraph-image`, width: 1200, height: 630, alt: `${SITE.name}: ${SITE.tagline}` };
/** Size of the files in public/img/results/*.png. */
export const RESULT_IMAGE_SIZE = { width: 1672, height: 941 };

export type ShareImage = { url: string; width: number; height: number; alt: string };

export const absoluteUrl = (path: string) => (/^https?:\/\//.test(path) ? path : path === "/" ? `${SITE.url}/` : `${SITE.url}${path}`);

/** Share image built from a result example in public/img/results. */
export const resultShareImage = (slug: string, alt: string): ShareImage => ({ url: `${SITE.url}/img/results/${slug}.png`, ...RESULT_IMAGE_SIZE, alt });

/** "Title | AI Beauty Styling" when it fits in 60 characters, otherwise the title alone. */
export function fitTitle(title: string) {
  const branded = `${title} | ${SITE.name}`;
  return branded.length <= 60 ? branded : title;
}

type Options = {
  title: string;
  description: string;
  path: string;
  /** Use the title exactly as given (no brand suffix). */
  exactTitle?: boolean;
  image?: ShareImage;
  type?: "website" | "article";
  publishedTime?: string;
  modifiedTime?: string;
  /** Force noindex even when the site is indexable (thin or unavailable pages). */
  noindex?: boolean;
};

/** One builder for every public page: canonical, Open Graph, Twitter card and robots (from SITE_INDEXABLE). */
export function buildMetadata(o: Options): Metadata {
  const title = o.exactTitle ? o.title : fitTitle(o.title);
  const url = absoluteUrl(o.path);
  const image = o.image ?? DEFAULT_OG_IMAGE;
  const robots = o.noindex ? { index: false, follow: true } : publicRobots();
  return {
    title: { absolute: title },
    description: o.description,
    alternates: { canonical: url },
    robots,
    openGraph: {
      title,
      description: o.description,
      url,
      siteName: SITE.name,
      locale: OG_LOCALE,
      type: o.type ?? "website",
      images: [{ url: image.url, width: image.width, height: image.height, alt: image.alt }],
      ...(o.type === "article" ? { publishedTime: o.publishedTime, modifiedTime: o.modifiedTime, authors: [SITE.name] } : {}),
    },
    twitter: { card: "summary_large_image", title, description: o.description, images: [image.url] },
  };
}

/** Metadata for pages that must never be indexed (login, register, dashboard...). Independent of SITE_INDEXABLE. */
export function privateMetadata(title: string, description?: string): Metadata {
  return { title, description, robots: privateRobots };
}
